static unsigned dah_farm_program_kind(const uint32_t *p,const uint8_t *valid){
 if(!p||!valid)return 0;
 const uint32_t *programs[]={&dah_farm_program_0[0][0],&dah_farm_program_1[0][0],&dah_farm_program_reflection[0][0]};
 const unsigned lengths[]={40,80,144};
 for(unsigned k=0;k<3;k++){unsigned i;for(i=0;i<lengths[k];i++)if(!valid[i]||p[i]!=programs[k][i])break;if(i==lengths[k])return 10+k;}return 0;
}
static float dah_farm_dp4(const float a[4],const float b[4]){return ((a[0]*b[0]+a[1]*b[1])+a[2]*b[2])+a[3]*b[3];}
static float dah_farm_dph(const float a[4],const float b[4]){return (a[0]*b[0]+a[1]*b[1])+a[2]*b[2]+b[3];}
static int dah_farm_vertex(unsigned kind,const float v[3][4],const float c[192][4],DahMenuVertex *out){
 if(kind!=10&&kind!=11)return 0;
 float p[4];memcpy(p,v[0],sizeof p);
 if(kind==11){
   if(!isfinite(v[1][2])||v[1][2]<-86.0f||v[1][2]>=103.0f)return 0;
   int base=86+(int)floorf(v[1][2]+0.001f);
   if(base<0||base+3>=192)return 0;
   float local[4];for(unsigned j=0;j<3;j++)local[j]=dah_farm_dp4(v[0],c[24+j]);local[3]=v[0][3];
   for(unsigned j=0;j<3;j++)p[j]=dah_farm_dph(local,c[base+j]);
   for(unsigned j=0;j<3;j++)out->diffuse[j]=c[base+3][j]*c[76][j]+c[77][j];
   out->diffuse[3]=dah_farm_dp4(p,c[16]);out->uv[0]=v[1][0];out->uv[1]=v[1][1];
 }else{memcpy(out->diffuse,v[2],sizeof out->diffuse);out->uv[0]=dah_farm_dp4(v[1],c[78]);out->uv[1]=dah_farm_dp4(v[1],c[79]);}
 float clip[4];for(unsigned j=0;j<4;j++)clip[j]=dah_farm_dph(p,c[36+j]);
 float reciprocal=dah_menu_rcc(clip[3]);
 for(unsigned j=0;j<3;j++)out->screen[j]=(clip[j]*c[2][j])*reciprocal+c[1][j];out->screen[3]=clip[3];out->fog=dah_farm_dp4(p,c[56]);
 for(unsigned j=0;j<4;j++)if(!isfinite(out->screen[j])||!isfinite(out->diffuse[j]))return 0;
 return isfinite(out->uv[0])&&isfinite(out->uv[1]);
}
/* Captured program 5: reflection, lighting and projected second texture
 * coordinate. The second coordinate is xyz because the retail pass uses a
 * cube map. Keep the observed instruction order, including R1/R5 dependencies. */
static float dah_farm_mul(float a,float b){return (a==0.0f||b==0.0f)?0.0f:a*b;}
static int dah_farm_reflection_vertex(const float v[4][4],const float c[192][4],
                                      DahMenuVertex *out,float tex1[4]){
    float local[3],normal[3],unit[3],reflected[3],clip[4];
    float len2,invlen,doubled,d0,d1,lit,recip;
    if(!v||!c||!out||!tex1)return 0;
    for(unsigned i=0;i<4;i++)for(unsigned j=0;j<4;j++)if(!isfinite(v[i][j]))return 0;
    for(unsigned j=0;j<3;j++){
        local[j]=dah_farm_dp4(v[0],c[32+j]);
        normal[j]=dah_menu_dot3(v[3],c[32+j]);
    }
    len2=dah_menu_dot3(local,local);
    invlen=len2==0.0f?INFINITY:1.0f/sqrtf(fabsf(len2));
    for(unsigned j=0;j<3;j++)unit[j]=dah_farm_mul(-invlen,local[j]);
    doubled=dah_menu_dot3(unit,normal);
    doubled+=doubled;
    for(unsigned j=0;j<3;j++)reflected[j]=dah_farm_mul(normal[j],doubled)-unit[j];

    /* R11.w/y are individually clamped before their product. */
    d0=fminf(dah_farm_dp4(v[0],c[16]),c[187][3]);
    d1=fminf(dah_farm_dp4(v[0],c[17]),c[187][3]);
    lit=fminf(dah_farm_mul(dah_farm_mul(d0,d1),c[77][3]),c[187][3]);
    for(unsigned j=0;j<3;j++){
        float ambient=dah_farm_mul(c[76][j],c[48][j])+c[77][j];
        out->diffuse[j]=dah_farm_mul(v[2][j],ambient);
    }
    out->diffuse[3]=dah_farm_mul(lit,v[2][3]);

    for(unsigned j=0;j<4;j++)clip[j]=dah_farm_dph(v[0],c[36+j]);
    recip=dah_menu_rcc(clip[3]);
    for(unsigned j=0;j<3;j++)out->screen[j]=dah_farm_mul(dah_farm_mul(clip[j],c[2][j]),recip)+c[1][j];
    out->screen[3]=clip[3];
    out->uv[0]=dah_farm_dp4(v[1],c[78]);
    out->uv[1]=dah_farm_dp4(v[1],c[79]);
    out->fog=dah_farm_dp4(v[0],c[56]);
    tex1[0]=dah_menu_dot3(reflected,c[28]);
    tex1[1]=dah_menu_dot3(reflected,c[30]);
    tex1[2]=dah_menu_dot3(reflected,c[29]);
    tex1[3]=c[187][3];
    for(unsigned j=0;j<4;j++)if(!isfinite(out->screen[j])||!isfinite(out->diffuse[j])||!isfinite(tex1[j]))return 0;
    return isfinite(out->uv[0])&&isfinite(out->uv[1])&&isfinite(out->fog);
}
